/** @type {Array<{re: RegExp, names: string[], out: string}>} */
const rx=[];
/** @type {Map<string, string>} */
const exact=new Map();
for(const [k,v] of Object.entries(ES)){
 // A template key is also kept as an exact key, so a call that passes the whole template (with its {name} placeholders) gets
 // that translation rather than a shorter key that happens to match the braces.
 exact.set(k,v);
 if(!k.includes('{'))continue;
 /** @type {string[]} */
 const names=[];const src=k.replace(/[.*+?^$()|[\]\\]/g,'\\$&').replace(/\{(\w+)\}/g,(_,n)=>{names.push(n);return '(.+?)';});
 rx.push({re:new RegExp(`^${src}$`),names,out:v});
}
export function detectLang(){
 try{const q=new URLSearchParams(location.search).get('lang');if(q==='es'||q==='en')return q;}catch{}
 try{const s=localStorage.getItem('welcome.lang');if(s==='es'||s==='en')return s;}catch{}
 for(const l of (typeof navigator==='undefined'?['en']:navigator.languages?.length?navigator.languages:[navigator.language||'en'])){const p=String(l).toLowerCase().slice(0,2);
   if(p==='es'||p==='en')return p;}
 return 'en';
}
export const lang=detectLang();
/**
 * @param {any} s the text to translate; anything that is not a string is returned as it is
 * @param {Record<string, any>} [vars] values for {name} placeholders
 * @returns {any}
 */
export function t(s,vars){
 if(typeof s!=='string')return s;
 let out=s;
 if(lang==='es'){
  const e=exact.get(s);
  if(e!==undefined)out=e;
  else for(const r of rx){const m=r.re.exec(s);
    if(m){const v=Object.fromEntries(r.names.map((n,i)=>[n,t(m[i+1])]));out=r.out.replace(/\{(\w+)\}/g,(_,n)=>v[n]);break;}}
 }
 return vars?out.replace(/\{(\w+)\}/g,(_,n)=>vars[n]??''):out;
}
const ATTRS=['title','aria-label','data-tooltip','placeholder'];
/** @type {Set<string|undefined>} */
const SKIP=new Set(['SCRIPT','STYLE','TEXTAREA','CODE']);
/** @param {any} node a DOM text node */
function fixText(node){
 const v=node.nodeValue;if(!v||!v.trim())return;
 const core=v.trim(),out=t(core);
 if(out!==core)node.nodeValue=v.replace(core,()=>out);
}
/** @param {any} el a DOM element */
function fixElement(el){for(const a of ATTRS){const v=el.getAttribute?.(a);if(v){const out=t(v);if(out!==v)el.setAttribute(a,out);}}}
/** @param {any} root a DOM node */
function walk(root){
 if(root.nodeType===3){if(!SKIP.has(root.parentNode?.nodeName))fixText(root);return;}
 if(root.nodeType!==1)return;
 fixElement(root);
 if(SKIP.has(root.nodeName))return;
 for(const n of root.childNodes)walk(n);
}
if(lang==='es'&&typeof document!=='undefined'){
 document.documentElement.lang='es';
 const start=()=>{
  walk(document.body);document.title=t(document.title);
  new MutationObserver(list=>{for(const m of list){
   if(m.type==='characterData'){if(!SKIP.has(m.target.parentNode?.nodeName))fixText(m.target);}
   else if(m.type==='attributes')fixElement(m.target);
   else for(const n of m.addedNodes)walk(n);
  }}).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:ATTRS});
 };
 if(document.body)start();else addEventListener('DOMContentLoaded',start);
}
/** Saves the language the user picks and reloads, so the whole page is drawn in it. */
/** @param {string} code */
export function setLanguage(code){if(code===lang||(code!=='en'&&code!=='es'))return;try{localStorage.setItem('welcome.lang',code);}catch{}location.reload();}
